import { v7 as uuidv7 } from 'uuid';

/**
 * The id generator for every table in this system.
 *
 * UUIDv7 is locked in CLAUDE.md and DECISIONS.md §9: changing it later means rewriting every
 * primary key and every foreign key that points at one. Two properties earn it that place:
 *
 *   1. It sorts chronologically, because the first 48 bits are a millisecond timestamp. That
 *      is what lets cursor pagination (#18) page by id alone instead of carrying a separate
 *      sort key and breaking ties.
 *   2. It is generated by the client of the database rather than by a sequence, so nothing
 *      leaks how many rows exist. An autoincrementing order id tells a competitor the
 *      platform's daily volume.
 *
 * Generated in the application, not by Postgres: `uuidv7()` is a PostgreSQL 18 function and
 * this project runs 16, so there is no `@default` that could produce one. That is also why
 * every `create` has to pass an id explicitly — see the comment on the Prisma models.
 */
export function newId(): string {
  return uuidv7();
}

/**
 * Whether a string is a UUID at all, in any version.
 *
 * For validating ids that arrive from outside. It deliberately does not check the version:
 * rejecting a v4 would turn "this id does not exist" into "this id is the wrong shape",
 * which tells a caller something about how ids are made for no benefit.
 */
const UUID_PATTERN = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;

export function isUuid(value: string): boolean {
  return UUID_PATTERN.test(value);
}
